'use strict';
// ov-arrange-core.js is openvibe-sdk/ui-layout for the browser, generated by scripts/build-arrange-core.js. The
// editor loads it from beside itself (ARRANGE_CORE_REV) so the one validator the SDK/server/AI use is also the
// one that refuses a bad move while a person drags. This checks the file is current and that the browser copy
// keeps the SDK's rules, including a docked overlay's own size.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { build } = require('../scripts/build-arrange-core');

const ROOT = path.join(__dirname, '..');
const generated = fs.readFileSync(path.join(ROOT, 'ov-arrange-core.js'), 'utf8');
const sdk = path.join(ROOT, 'node_modules', 'openvibe-sdk');
assert.ok(fs.existsSync(path.join(sdk, 'src', 'ui-layout.js')), 'the pinned openvibe-sdk has ui-layout (pin 0.151.0 or later)');
assert.equal(generated, build(sdk), 'ov-arrange-core.js is current: run node scripts/build-arrange-core.js');

const saved = global.window;
global.window = global;
delete require.cache[require.resolve('../ov-arrange-core.js')];
require('../ov-arrange-core.js');
const core = global.OVArrangeCore;
assert.ok(core && typeof core.validate === 'function' && typeof core.applyDefaults === 'function' && typeof core.merge === 'function', 'the browser core exposes validate, applyDefaults and merge');
assert.equal(core.PRESSED_PX, 44);

const catalog = {
    id: 'bot.overlay', version: 1, name: 'Robot over a stream', devices: ['phone', 'tablet', 'computer'],
    grid: { columns: { phone: 4, tablet: 8, computer: 12 }, cell_px: { phone: 64, tablet: 64, computer: 64 } },
    theme_tokens: ['danger', 'surface', 'accent'],
    parts: [
        { id: 'stop', name: 'Stop', kind: 'button', required: true, pressed: true, min: { w: 2, h: 2, px: 56 }, styles: { tints: ['danger'], shapes: ['round'], label: true }, bindings: { keys: [], gamepad: [] } },
        { id: 'stick', name: 'Stick', kind: 'stick', required: false, pressed: true, min: { w: 2, h: 2 }, styles: { tints: ['surface'], shapes: ['round'], label: false }, bindings: { keys: ['W'], gamepad: [] } },
    ],
};
const part = (id, place) => ({ id, visible: true, place, style: { tint: id === 'stop' ? 'danger' : 'surface', shape: 'round', opacity: 1, label: id === 'stop' }, bindings: { keys: [], gamepad: [] } });
const layout = (stop = { dock: 'right', order: 0, w: 2, h: 2 }) => ({
    surface: 'bot.overlay', surface_version: 1, device: 'phone', name: 'Mine', author: { name: 'Ana' }, sharing: 'private',
    parts: [part('stop', stop), part('stick', { dock: 'left', order: 0, w: 2, h: 2 })],
});
assert.deepEqual(core.validate(catalog, layout()), { ok: true, reasons: [] });
assert.ok(core.validate(catalog, layout({ dock: 'right', order: 0, w: 1, h: 1 })).reasons.includes('Stop has to be at least 2 × 2 cells.'));
const covered = layout();
covered.parts[1].place = { dock: 'right', order: 0, w: 2, h: 2 };
assert.ok(core.validate(catalog, covered).reasons.some((r) => /Stick covers Stop/.test(r)));
const defaults = core.applyDefaults(catalog, 'phone');
assert.deepEqual(core.validate(catalog, defaults), { ok: true, reasons: [] }, 'the SDK defaults are valid');
assert.equal(core.merge(layout(), { parts: [{ id: 'stick', style: { opacity: 0.5 } }] }).parts[1].style.opacity, 0.5);
console.log('ov-arrange-core: current with the SDK and its rules, dock sizes and coverage included');
if (saved === undefined) delete global.window;
